<template>
    <section class="section platform-portal"><div class="container">
        <div class="section-heading"><div><p class="eyebrow">Voca control centre</p><h1>Superadmin portal</h1><p class="muted">Control every organisation, administrator, ministry brand and account from one place.</p></div><button class="button" @click="showCreate = !showCreate">{{ showCreate ? 'Cancel' : 'New organisation' }}</button></div>
        <p v-if="message" class="status-card">{{ message }}</p>
        <form v-if="showCreate" class="glass-card platform-create" @submit.prevent="createOrganisation"><label>Organisation name<input v-model="createForm.name" required /></label><label>Subdomain<input v-model="createForm.slug" placeholder="church-name" required /></label><label>Plan<select v-model="createForm.plan"><option>standard</option><option>pro</option><option>enterprise</option></select></label><button class="button" :disabled="saving">Create</button></form>

        <div class="platform-stats"><article class="glass-card"><strong>{{ organisations.length }}</strong><span>Organisations</span></article><article class="glass-card"><strong>{{ activeCount }}</strong><span>Active</span></article><article class="glass-card"><strong>{{ totalAdmins }}</strong><span>Admins & owners</span></article><article class="glass-card"><strong>{{ totalMinistries }}</strong><span>Ministries</span></article></div>

        <div class="platform-layout">
            <aside class="glass-card organisation-list"><label class="search-field">Find an organisation<input v-model="search" type="search" placeholder="Name or subdomain" /></label><button v-for="item in filtered" :key="item.id" class="organisation-row" :class="{ active: selected?.id === item.id }" @click="select(item)"><span><strong>{{ item.name }}</strong><small>{{ item.slug }}.app.voca.co.za</small></span><i :class="`status-${item.status}`">{{ item.status }}</i></button></aside>
            <main v-if="selected" class="platform-detail">
                <div class="glass-card detail-heading"><div><p class="eyebrow">{{ selected.plan }} plan</p><h2>{{ selected.name }}</h2><p>{{ selected.users_count }} users · {{ selected.ministries_count }} ministries</p></div><div class="button-row"><a class="button ghost" :href="tenantUrl" target="_blank">Open portal</a><button class="button ghost" @click="toggleStatus">{{ selected.status === 'active' ? 'Suspend' : 'Activate' }}</button></div></div>
                <nav class="platform-tabs"><button v-for="tab in tabs" :key="tab" :class="{ active: activeTab === tab }" @click="activeTab = tab">{{ tab }}</button></nav>

                <form v-if="activeTab === 'Overview'" class="glass-card admin-panel" @submit.prevent="saveOrganisation"><h3>Organisation settings</h3><div class="field-row"><label>Name<input v-model="edit.name" /></label><label>Subdomain slug<input v-model="edit.slug" /></label><label>Plan<input v-model="edit.plan" /></label></div><label>Storage limit (bytes)<input v-model.number="edit.storage_limit_bytes" type="number" min="0" /></label><button class="button" :disabled="saving">Save settings</button></form>
                <form v-if="activeTab === 'Branding'" class="glass-card admin-panel" @submit.prevent="saveBranding"><h3>White-label identity</h3><div class="field-row"><label>Display name<input v-model="branding.name" /></label><label>Tagline<input v-model="branding.tagline" /></label></div><label>About this ministry<textarea v-model="branding.description" rows="4"></textarea></label><label>Logo URL<input v-model="branding.logo_url" type="url" /></label><label>Home page thumbnail URL<input v-model="branding.thumbnail_url" type="url" /></label><label>Favicon URL<input v-model="branding.favicon_url" type="url" /></label><label>Rumble channel or live URL<input v-model="branding.rumble_url" type="url" /></label><div class="field-row"><label>Primary colour<input v-model="branding.primary_colour" type="color" /></label><label>Secondary colour<input v-model="branding.secondary_colour" type="color" /></label></div><div class="social-editor"><h3>Social links</h3><div class="field-row"><label>Facebook<input v-model="branding.social_links.facebook" type="url" /></label><label>Instagram<input v-model="branding.social_links.instagram" type="url" /></label></div><div class="field-row"><label>YouTube<input v-model="branding.social_links.youtube" type="url" /></label><label>TikTok<input v-model="branding.social_links.tiktok" type="url" /></label></div><label>Website<input v-model="branding.social_links.website" type="url" /></label></div><button class="button" :disabled="saving">Save white label</button></form>
                <form v-if="activeTab === 'Modules'" class="glass-card admin-panel" @submit.prevent="saveModules"><h3>Features and modules</h3><div class="module-grid"><label v-for="(enabled, key) in modules" :key="key" class="toggle-row"><input v-model="modules[key]" type="checkbox" /><span>{{ moduleLabels[key] || key }}</span></label></div><button class="button" :disabled="saving">Save modules</button></form>
                <section v-if="activeTab === 'Admins'" class="glass-card admin-panel"><h3>Administrators and account access</h3><form class="inline-form compact" @submit.prevent="addUser"><input v-model="newUser.name" placeholder="Full name" required /><input v-model="newUser.email" type="email" placeholder="Email" required /><select v-model="newUser.role"><option value="admin">Admin</option><option value="owner">Owner</option><option value="user">User</option></select><button class="button">Add</button></form><div class="account-list"><article v-for="membership in selected.memberships" :key="membership.id"><span><strong>{{ membership.user.name }}</strong><small>{{ membership.user.email }}</small></span><select v-model="membership.role" @change="updateMembership(membership)"><option value="owner">Owner</option><option value="admin">Admin</option><option value="user">User</option></select><span>{{ membership.status }}</span><button class="button ghost" @click="setStatus(membership)">{{ membership.status === 'active' ? 'Suspend' : 'Restore' }}</button><button class="button ghost" :disabled="membership.status !== 'active'" @click="resendInvite(membership)">Send invitation</button><button class="button ghost" :disabled="membership.status !== 'active'" @click="impersonate(membership.user)">Log in as</button><button class="icon-button" title="Remove access" @click="removeUser(membership)">×</button></article></div></section>
            </main>
            <div v-else class="glass-card empty-state">Select an organisation to manage it.</div>
        </div>
    </div></section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
const organisations = ref([]), selected = ref(null), search = ref(''), activeTab = ref('Overview'), saving = ref(false), showCreate = ref(false), message = ref('');
const tabs = ['Overview', 'Branding', 'Modules', 'Admins'];
const createForm = reactive({ name: '', slug: '', plan: 'standard' }); const edit = reactive({}); const branding = reactive({}); const modules = reactive({}); const newUser = reactive({ name: '', email: '', role: 'admin' });
const moduleLabels = { livestreaming: 'Livestreaming', events: 'Events', inspiration: 'Inspiration', schedules: 'Scheduling', announcements: 'Announcements', kanban: 'Kanban boards', bookings: 'Bookings', public_ministries: 'Public ministries' };
const activeCount = computed(() => organisations.value.filter(o => o.status === 'active').length); const totalMinistries = computed(() => organisations.value.reduce((n, o) => n + o.ministries_count, 0)); const totalAdmins = computed(() => organisations.value.reduce((n, o) => n + o.memberships.filter(m => ['owner', 'admin'].includes(m.role)).length, 0));
const filtered = computed(() => { const q = search.value.toLowerCase(); return organisations.value.filter(o => `${o.name} ${o.slug}`.toLowerCase().includes(q)); }); const tenantUrl = computed(() => `${window.location.protocol}//${selected.value.slug}.${window.location.host.replace(/^[^.]+\./, '')}`);
const notify = text => { message.value = text; window.setTimeout(() => message.value = '', 3000); };
const load = async (keepId = selected.value?.id) => { const { data } = await window.axios.get('/api/platform/organisations'); organisations.value = data.data.data; if (keepId) select(organisations.value.find(o => o.id === keepId)); };
const select = item => { if (!item) return; selected.value = item; Object.assign(edit, { name: item.name, slug: item.slug, plan: item.plan, storage_limit_bytes: item.storage_limit_bytes || 0 }); Object.keys(branding).forEach(k => delete branding[k]); Object.assign(branding, item.branding || {}); branding.social_links ||= {}; Object.keys(modules).forEach(k => delete modules[k]); Object.assign(modules, item.modules || {}); };
const patch = async payload => { saving.value = true; try { await window.axios.patch(`/api/platform/organisations/${selected.value.id}`, payload); await load(selected.value.id); notify('Changes saved.'); } finally { saving.value = false; } };
const saveOrganisation = () => patch(edit); const saveBranding = () => patch({ branding }); const saveModules = () => patch({ modules });
const toggleStatus = () => patch({ status: selected.value.status === 'active' ? 'suspended' : 'active' });
const createOrganisation = async () => { saving.value = true; try { const { data } = await window.axios.post('/api/platform/organisations', createForm); await load(); select(organisations.value.find(o => o.id === data.data.id)); Object.assign(createForm, { name: '', slug: '', plan: 'standard' }); showCreate.value = false; notify('Organisation created.'); } finally { saving.value = false; } };
const addUser = async () => { try { const { data } = await window.axios.post(`/api/platform/organisations/${selected.value.id}/users`, newUser); Object.assign(newUser, { name: '', email: '', role: 'admin' }); await load(selected.value.id); notify(data.invitation_sent ? 'Invitation sent.' : 'Access exists. A link was sent recently; try resending shortly.'); } catch (e) { notify(e?.response?.data?.message || 'Unable to invite user.'); } };
const updateMembership = async membership => { try { await window.axios.patch(`/api/platform/organisations/${selected.value.id}/users/${membership.id}`, { role: membership.role }); notify('Role updated.'); } catch (e) { notify(e?.response?.data?.message || 'Unable to update role.'); } finally { await load(selected.value.id); } };
const setStatus = async membership => { try { await window.axios.patch(`/api/platform/organisations/${selected.value.id}/users/${membership.id}`, { status: membership.status === 'active' ? 'suspended' : 'active' }); await load(selected.value.id); notify('Access updated.'); } catch (e) { notify(e?.response?.data?.message || 'Unable to update access.'); } };
const resendInvite = async membership => { try { const { data } = await window.axios.post(`/api/platform/organisations/${selected.value.id}/users/${membership.id}/invite`); notify(data.message); } catch (e) { notify(e?.response?.data?.message || 'Unable to send invitation.'); } };
const removeUser = async membership => { if (!window.confirm(`Remove ${membership.user.name} from this organisation?`)) return; try { await window.axios.delete(`/api/platform/organisations/${selected.value.id}/users/${membership.id}`); await load(selected.value.id); } catch (e) { notify(e?.response?.data?.message || 'Unable to remove access.'); } };
const impersonate = async user => { if (!window.confirm(`Log in as ${user.name}? You can return using the banner at the top.`)) return; await window.axios.post(`/api/platform/organisations/${selected.value.id}/impersonate/${user.id}`); window.location.assign('/admin'); };
onMounted(async () => { await load(); if (organisations.value.length) select(organisations.value[0]); });
</script>
